Definition AMIC : Z := 0x60dd0.           (* [comment removed for export] *)
Definition AMIC_RET : Z := 0x60ef0.       (* [comment removed for export] *)
Definition MIC_FRAME : Z := 2192.

Section MIC.
  Context {HCEIL : HeapCeil}.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : word -> option byte) (ls rs : list byte) (lo fn D : Z).
  Notation p1 := (bv_unsigned a2).
  Notation p2 := (bv_unsigned a3).
  Notation n := (bv_unsigned a4).
  Hypothesis Ha1 : a1 = Z_to_bv 64 fn.
  Hypothesis FNR : 0 <= fn < 2^64 /\ fn mod 2 = 0.
  Hypothesis LS : Z.of_nat (length ls) = n.
  Hypothesis LR : length rs = length ls.
  Hypothesis E1 : bytes_at asegs m p1 ls.
  Hypothesis E2 : bytes_at asegs m p2 rs.
  Hypothesis ACC1 : accessible m p1 n.
  Hypothesis ACC2 : accessible m p2 n.
  Hypothesis SV1 : shvis m p1 (p1 + n).
  Hypothesis SV2 : shvis m p2 (p2 + n).
  Hypothesis ST0 : stk asegs m lo (bv_unsigned sp).
  Hypothesis CEIL : aceil <= lo.
  Hypothesis D80 : 80 <= D.
  Hypothesis LO : lo <= bv_unsigned sp - MIC_FRAME - D.
  Hypothesis MI : mem_inv asegs m.
  Hypothesis AC : ACONST m.
  Hypothesis N40 : n <= 2^40.
  Hypothesis INM1 : in_app_mem p1 (p1 + n).
  Hypothesis INM2 : in_app_mem p2 (p2 + n).
  Hypothesis DJ1 : p1 + n <= lo \/ bv_unsigned sp <= p1.
  Hypothesis DJ2 : p2 + n <= lo \/ bv_unsigned sp <= p2.
  Hypothesis CFm : rw_cells asegs m 1814694 [C1 (b8 1); C1 (b8 1)].   (* [comment removed for export] *)

  Notation RES := (memcmp_model (map (@bv_unsigned 8) ls) (map (@bv_unsigned 8) rs)).
  Definition mic_post : machine_state -> Prop :=
    fun ms' => exists x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x28 x29 x30 x31 m',
      ms' = MS (mkR ra sp gp tp x5 x6 x7 s0 s1 (wz RES) x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
               F (ret_pc ra) fc None m' (seg_rom asegs)
      /\ munch [(bv_unsigned sp - 2192 - D, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
      /\ stk asegs m' lo (bv_unsigned sp)
      /\ ACONST m'.
  Notation POST := mic_post.
  Notation SP2 := (Z_to_bv 64 (bv_unsigned sp + -2192)).
  Notation W := [(bv_unsigned sp - 2192 - D, bv_unsigned sp)].
  (* [comment removed for export] *)
  Notation RST pc x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 mm :=
    (MS (mkR x1 SP2 gp tp x5 x6 x7 sp a4 x10 x11 x12 x13 x14 x15 x16 x17 a3 ra a2 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).
  Notation FRAME mm := (rw_cells asegs mm (bv_unsigned sp + -104)
                         [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).
  Notation CF := (Z_to_bv 64 1814440).   (* [comment removed for export] *)

  (* [comment removed for export] *)
  Definition fn_post (x22 x23 x25 x26 x27 : word) : machine_state -> Prop :=
    fun ms' => exists (x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x28 x29 x30 x31 : word) (mm' : word -> option byte) (fj' : list byte),
      ms' = MS (mkR (Z_to_bv 64 AMIC_RET) SP2 gp tp x5 x6 x7 sp a4 (wz RES) x11 x12 x13 x14 x15 x16 x17 a3 ra a2 (Z_to_bv 64 fn) x22 x23 CF x25 x26 x27 x28 x29 x30 x31)
               F (Z_to_bv 64 AMIC_RET) fc None mm' (seg_rom asegs)
      /\ mem_inv asegs mm' /\ munch W m mm' /\ wmono asegs m mm'
      /\ FRAME mm' /\ rw_cells asegs mm' (bv_unsigned sp + -2192) [CB 2088 fj'] /\ stk asegs mm' lo (bv_unsigned sp + -2192).
  Hypothesis FNSPEC : forall (x5 x6 x7 x13 x14 x15 x16 x17 x22 x23 x25 x26 x27 x28 x29 x30 x31 : word) (mm : word -> option byte) (fj : list byte),
    mem_inv asegs mm -> munch W m mm -> wmono asegs m mm ->
    FRAME mm -> rw_cells asegs mm (bv_unsigned sp + -2192) [CB 2088 fj] -> stk asegs mm lo (bv_unsigned sp + -2192) ->
    evt asegs (fn_post x22 x23 x25 x26 x27)
      (MS (mkR (Z_to_bv 64 AMIC_RET) SP2 gp tp x5 x6 x7 sp a4 a2 a3 a4 x13 x14 x15 x16 x17 a3 ra a2 (Z_to_bv 64 fn) x22 x23 CF x25 x26 x27 x28 x29 x30 x31)
          F (Z_to_bv 64 fn) fc None mm (seg_rom asegs)).

  (* [comment removed for export] *)
  Ltac land64_to_mod K :=
    change 18446744073709551615 with (Z.ones 64) in K; rewrite ?Z.land_ones in K by lia;
    change (2 ^ 64) with 18446744073709551616 in K.
  Ltac prep :=
    intros; acb; unfold MIC_FRAME, AMIC_RET in *;
    pose proof INM1 as INM1'; unfold in_app_mem, AHI_LO, AAPP_HI in INM1'; rewrite ASHADOW_BASE_val in INM1';
    pose proof INM2 as INM2'; unfold in_app_mem, AHI_LO, AAPP_HI in INM2'; rewrite ASHADOW_BASE_val in INM2';
    pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
    pose proof (bv_unsigned_in_range 64 a2) as A2R; unfold bv_modulus in A2R; change (2 ^ Z.of_N 64) with (2^64) in A2R;
    pose proof (bv_unsigned_in_range 64 a3) as A3R; unfold bv_modulus in A3R; change (2 ^ Z.of_N 64) with (2^64) in A3R;
    pose proof (bv_unsigned_in_range 64 a4) as A4R; unfold bv_modulus in A4R; change (2 ^ Z.of_N 64) with (2^64) in A4R.

  (* [comment removed for export] *)
  Section JF.
    Variables (mm : word -> option byte) (fjunk : list byte).
    Hypothesis MIm : mem_inv asegs mm.
    Hypothesis FR1 : FRAME mm.
    Hypothesis FR : rw_cells asegs mm (bv_unsigned sp + -2192) [CB 2088 fjunk].
    Hypothesis STm : stk asegs mm lo (bv_unsigned sp + -2192).
    Hypothesis MU : munch W m mm.
    Hypothesis WM : wmono asegs m mm.

